return ['domain'=>'press-permit-core>= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);>= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1: 2);for Posts, Pages, Categories, Tags - Development (trunk):','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11 ? 0 : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:58+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions позволяет вам включать или отключать доступ к записям, страницам, категориям, тегам и многому другому.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Редактировать тег для всех типов записей','Edit Tag for Posts'=>'Редактировать тег для записей','Advanced Custom Fields'=>'Расширенные пользовательские поля','Control front-end access to Field Groups with advanced permission management.'=>'Управляйте доступом к группам полей на фронтенде с помощью расширенного управления разрешениями.','Control access to Field Groups'=>'Управление доступом к группам полей','Front-end visibility restrictions'=>'Ограничения видимости на фронтенде','Integration with permission groups'=>'Интеграция с группами разрешений','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Совместимость с редактированием разрешений в Beaver Builder.','Beaver editor integration'=>'Интеграция с редактором Beaver','Widget-level permission controls'=>'Управление разрешениями на уровне виджетов','Template access restrictions'=>'Ограничения доступа к шаблонам','bbPress Forums'=>'Форумы bbPress','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Специфические разрешения для форума bbPress с детальным контролем доступа к форуму и участию.','Forum-specific permissions'=>'Специфические разрешения для форумов','Topic creation restrictions'=>'Ограничения на создание тем','Forum access controls'=>'Контроль доступа к форуму','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Назначайте разрешения на записи и таксономии для групп BuddyPress для улучшенного контроля контента.','Assign post permissions to BuddyPress groups'=>'Назначьте разрешения на записи группам BuddyPress','Assign term permissions to BuddyPress groups'=>'Назначить разрешения на термины для групп BuddyPress','Group-based content permissions'=>'Разрешения на контент на основе групп','CMS Tree View'=>'Дерево CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'Совместимость с редактированием разрешений в дереве CMS.','Permission-aware tree view'=>'Дерево с учетом разрешений','Hierarchical content controls'=>'Иерархические элементы управления контентом','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Совместимость с редактированием разрешений в Elementor.','Elementor editor integration'=>'Интеграция редактора Elementor','The Events Calendar'=>'Календарь событий','Apply permission controls to events and event-related content.'=>'Применить элементы управления разрешениями к событиям и связанному контенту.','Event post permissions'=>'Разрешения на публикации событий','Event taxonomy controls'=>'Элементы управления таксономией событий','Nested Pages'=>'Вложенные страницы','Compatibility with Edit Permissions in Nested Pages.'=>'Совместимость с редактированием разрешений во вложенных страницах.','Permission-aware nested view'=>'Вид с учетом разрешений во вложенных страницах','Quick edit integration'=>'Интеграция быстрого редактирования','PublishPress Statuses'=>'Статусы PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Совместимость с плагином статусов PublishPress.','Custom status permissions'=>'Разрешения для пользовательских статусов','Workflow-specific access controls'=>'Специфические для рабочего процесса контроль доступа','Status-based editing capabilities'=>'Редактирование на основе статуса','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Фильтруйте результаты поиска на основе разрешений просмотра для безопасного обнаружения контента.','Search result filtering'=>'Фильтрация результатов поиска','Permission-aware indexing'=>'Индексация с учетом разрешений','Secure content discovery'=>'Безопасное обнаружение контента','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Совместимость с фильтрацией терминов SearchWP для расширенных возможностей поиска.','Permission-aware search results'=>'Результаты поиска с учетом разрешений','Term-based filtering'=>'Фильтрация на основе терминов','Advanced search controls'=>'Расширенные параметры поиска','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Применение контроля разрешений к продуктам WooCommerce и категориям продуктов.','Product permissions'=>'Разрешения на продукты','Product category controls'=>'Контроль категорий продуктов','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Поддержка многоязычности с синхронизацией разрешений по переводу контента.','Permission synchronization across translations'=>'Синхронизация разрешений между переводами','Language-specific content access'=>'Доступ к контенту на основе языка','Multilingual permission management'=>'Многоязычное управление разрешениями','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Исключить ограниченные записи из XML-карт сайта для поддержания правильной индексации SEO.','Sitemap filtering for restricted content'=>'Фильтрация карты сайта для ограниченного контента','Search engine visibility controls'=>'Управление видимостью в поисковых системах','Permission-aware XML sitemaps'=>'XML-карты сайта с учетом разрешений','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Совместимость с конструктором YooTheme и разрешениями терминов.','Builder interface compatibility'=>'Совместимость интерфейса конструктора','Term permission integration'=>'Интеграция разрешений терминов','Template access controls'=>'Управление доступом к шаблонам','Viewing'=>'Просмотр','Access Circles'=>'Круги доступа','Editing Permissions'=>'Разрешения на редактирование','Compatibility Pack'=>'Пакет совместимости','Teaser'=>'Тизер','File Access'=>'Доступ к файлам','Membership'=>'Членство','User Posts'=>'Публикации пользователей','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Круги видимости и редакционные круги блокируют доступ к контенту, не созданному другими членами группы.','Post-specific and category-specific permissions for creation and editing.'=>'Разрешения на создание и редактирование для конкретных записей и категорий.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Интеграция с ACF, bbPress, BuddyPress, Relevanssi, WPML и другими плагинами; улучшенная поддержка Multisite.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'На фронтенде сайта отображайте текст-тизер для нечитаемых записей вместо того, чтобы скрывать их.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Ограничьте прямые запросы к файлам в зависимости от доступа пользователя к странице, к которой прикреплен файл.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Настройка ограничения доступа по времени путем задержки или истечения срока действия членства в группе разрешений.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Автосоздание страницы для каждого пользователя с заданными ролями. Совместимо с несколькими плагинами для команды / персонала.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Круги видимости и редакционные круги блокируют доступ к контенту, не созданному другими членами группы. Любая роль WP, группа BuddyPress или пользовательская группа могут быть отмечены как круг для заданных типов записей.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Поддерживает специфические разрешения для редактирования, назначения терминов и выбора родительской страницы. В сочетании с другими модулями поддерживает статусы рабочего процесса, PublishPress и PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Добавляет совместимость или интеграцию с ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML и различными другими плагинами. Настройте любую группу BuddyPress как группу разрешений. Для multisite предоставляет группы разрешений на уровне сети.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'На фронтенде сайта заменяйте нечитаемый контент текстом-заглушкой. Может быть включен для любого типа записи. Предоставляются пользовательские фильтры, но программирование не требуется для базового использования.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Фильтрует прямой доступ к файлам на основе доступа пользователя к записям, к которым прикреплен файл. Дополнительная настройка не требуется. Создает/модифицирует файл .htaccess в папке загрузок (и в основной папке для multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Позволяет ограничивать членство в группе разрешений по дате (отложенное и/или запланированное на истечение). Простой интерфейс выбора даты вместе с выбором членства в группе.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Создавайте или синхронизируйте записи в соответствии с пользователями. Разработан для плагинов команды / персонала, но с широким потенциалом использования.','If you like %s, please leave us a %s rating. Thank you!'=>'Если вам нравится %s, пожалуйста, оставьте нам оценку %s. Спасибо!','About PublishPress Permissions'=>'О PublishPress разрешениях','About'=>'О плагине','Permissions Documentation'=>'Документация по разрешениям','Documentation'=>'Документация','Contact the PublishPress team'=>'Свяжитесь с командой PublishPress','Contact'=>'Контакт','Permission Group'=>'Группа разрешений','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Особые разрешения: ограничения ("Заблокировано") имеют приоритет над дополнениями ("Включено")','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Особые разрешения: никакие ограничения ("Запрещено") не могут быть применены к определенным пользователем группам','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Доступно назначение дополнительных ролей для метагрупп {All} и {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Разрешить метагруппам {Все} и {Анонимные} предоставлять определенные разрешения на чтение для личного контента','Users who have specific editing permissions for a post or attachment can also delete it'=>'Пользователи, имеющие специфические разрешения на редактирование поста или вложения, также могут удалить его','Users who have custom editing permissions for an attachment can also delete it'=>'Пользователи, имеющие пользовательские разрешения на редактирование вложения, также могут удалить его','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Отключите фильтрацию внешнего интерфейса, если зарегистрированный пользователь является администратором контента (обычно фильтрация для принудительного включения читаемых личных записей в список get_pages (), количество записей и т. д.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Отключить фильтрацию внешнего интерфейса для всех пользователей (с учетом ограничения PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Список типов записей, разделенных запятыми, для ограничения эффекта PP_UNFILTERED_FRONT и apply_filters( "presspermit_skip_cap_filtering" )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Особые разрешения: дополнения ("Включено") не применяются, не могут быть назначены','Don\'t assign or apply specific permissions for the \'post\' type'=>'Не назначайте и не применяйте определенные разрешения для типа "Записи"','Don\'t assign or apply specific permissions for the \'page\' type'=>'Не назначайте и не применяйте определенные разрешения для типа "страница"','Don\'t assign or apply specific permissions for the \'media\' type'=>'Не назначайте и не применяйте определенные разрешения для типа "медиа"','Don\'t assign or apply specific permissions for the specified custom post type'=>'Не назначайте и не применяйте определенные разрешения для указанного пользовательского типа записи','Include scheduled posts in the posts query if user can edit them'=>'Включите запланированные записи в запрос "Публикации", если пользователь может их редактировать','Don\'t filter term post counts in get_terms() call'=>'Не фильтруйте количество терминов записей в вызове get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Оставляйте нечитаемые записи в меню навигации WP','Don\'t apply CSS to hide empty Nav Menus'=>'Не применять CSS для скрытия пустых меню навигации','For legacy Nav Menus, hide empty nav menu div'=>'Для устаревших меню навигации скрыть пустой div меню навигации','Leave terms with no readable posts on WP Navigation Menus'=>'Оставьте термины без читаемых записей в меню навигации WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Когда тизер применяется с включенным перенаправлением, добавьте оригинальный URL как аргумент redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Для совместимости с тизером укажите аргумент перенаправления, который использовать вместо redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Для совместимости с тизером укажите дополнительный аргумент перенаправления, отличный от redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Для совместимости с тизером предотвратите добавление аргумента pp_permissions к перенаправлениям','Filter priority for \'get_pages\' filter (default: 1)'=>'Приоритет для фильтра "get_pages" (по умолчанию: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Не включайте читаемые личные страницы в виджет Страницы или другие результаты wp_list_pages() / get_pages()','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Если некоторые страницы были удалены из результатов get_pages(), измените соответствующие значения post_parent дочерних страниц на видимый предок','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Никогда не изменяйте значение post_parent в результирующем наборе get_pages(), даже если некоторые страницы были заблокированы','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Для повышения производительности измените запрос базы данных get_pages(), чтобы возвращать только подмножество полей, исключая post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Не применять контентный тизер к результатам get_pages() (оставьте невидимые посты скрытыми)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Если некоторые термины были удалены из результатов get_terms(), измените соответствующие родительские значения дочерних терминов на видимого предка','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Никогда не изменяйте родительское значение в результирующем наборе get_terms(), даже если некоторые термины были подавлены','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Установите автора на текущего пользователя, если назначены возможности autoset_post_author / autoset_page_author','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Оставьте медиатеку с обычными критериями доступа, основанными на возможностях роли пользователя','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Учитывайте решения для загрузки на фронт-энде, которые требуют возможностей редактирования страниц для асинхронного запроса загрузки','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Обрабатывайте медиа, прикрепленные к незарегистрированным типам записей, как неприкрепленные, чтобы избежать неправильной и запутанной фильтрации','Attached Files Private setting available'=>'Доступна настройка "Прикрепленные файлы - Частный"','Comma-separated list of mime types to exclude from File Access filtering'=>'Список mime-типов, разделенных запятыми, для исключения из фильтрации доступа к файлам','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Список mime-типов через запятую для включения в фильтрацию доступа к файлам (с обходом других)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Когда доступ к файлу заблокирован, не устанавливайте свойство WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'HTTP статус-код, который отправить, когда доступ к файлу заблокирован','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'В списке пользователей группы разрешений в настраиваемом столбце представляют собой ссылки фильтра списка, а не ссылки редактирования группы.','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Разблокировать разрешения > Настройки > Ядро > Серверная часть администратора > "Скрыть не редактируемые записи"','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'Внутри скрипта async-upload.php отфильтруйте получение автора вложения, которое они только что загрузили','Don\'t filter comment display or moderation within wp-admin'=>'Не фильтруйте отображение комментариев или модерацию в wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Позволить администраторам быть добавленными в группы разрешений, даже если они не ограничены','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Если ветви страницы назначены разрешения на распространение, замените все явно назначенные разрешения на подстраницах','Max number of specific permissions to insert in a single database query (default 1000)'=>'Максимальное количество определенных разрешений для вставки в один запрос базы данных (по умолчанию 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Не настраивайте индексы меню администратора для размещения меню разрешений в разделе Пользователи','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Не добавляйте меню разрешений. Вместо этого добавьте пункты меню в меню "Пользователи" и "Настройки".','Customize Permissions screen title for Groups'=>'Настройте заголовок экрана Разрешений для Групп','Customize Permission Groups caption on user profile'=>'Настройте заголовок Групп Разрешений на профиле пользователя','Only one group is selectable on Add User screen'=>'На экране Добавить пользователя можно выбрать только одну группу','Only one group is selectable on Edit User screen'=>'На экране Редактировать пользователя можно выбрать только одну группу','Display a custom hint on Permissions > User Groups'=>'Отобразите пользовательский подсказку на Разрешения > Группы пользователей','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Максимальное количество неиерархических записей / терминов для одновременного отображения (на странице)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Максимальное количество иерархических записей / терминов для одновременного отображения (на странице)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Отключите автоматическое определение того, сколько уровней дерева страниц нужно сделать видимыми по умолчанию. Вместо этого используйте указанное значение.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Целевое количество видимых страниц/terms, используемых для автоматического определения количества видимых уровней','Make search function on the post selection metabox look at post content'=>'Сделайте функцию поиска в метабоксе выбора записей, чтобы просмотреть содержимое записи','Make search function on the post selection metabox look at post excerpt'=>'Сделайте функцию поиска в метабоксе выбора поста посмотрите выдержку из поста','Search by last name instead of display name'=>'Поиск по фамилии вместо отображаемого имени','User field to search by default'=>'Поле пользователя для поиска по умолчанию','User meta fields selectable for search (comma-separated)'=>'Пользовательские мета-поля, выбираемые для поиска (через запятую)','User meta fields which should be treated as numeric (comma-separated)'=>'Пользовательские мета-поля, которые должны обрабатываться как числовые (через запятую)','User meta fields which should be treated as boolean (comma-separated)'=>'Пользовательские мета-поля, которые следует рассматривать как логические (через запятую)','Use display name for search results instead of user_login'=>'Используйте отображаемое имя для результатов поиска вместо user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'При синхронизации метагрупп ролей с текущими ролями WP не удаляйте группы для ранее определенных ролей WP.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Принудительное обнаружение ролей пользователей WP, которые добавляются динамически, но не сохраняются в базе данных WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'Чтобы сэкономить память при интерфейсном доступе, не регистрируйте никаких фильтров, связанных с редактированием контента','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Прикрепленные носители не содержат комментариев, поэтому не добавляйте предложения к запросам комментариев для них','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Уменьшите нагрузку на запросы страниц (в get_pages() и wp-admin), указав поля по умолчанию в списке наборов, который не включает post_content','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Уменьшите нагрузку на запрос записей wp-admin, указав поля по умолчанию в списке наборов, который не включает post_content','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Уменьшите нагрузку на медиа-запрос wp-admin, указав поля по умолчанию в списке наборов, который не включает post_content','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Уменьшите нагрузку на запрос wp-admin для указанного пользовательского типа записи, указав поля по умолчанию в списке наборов, который не включает post_content','Work around database setup warnings (at plugin activation) on some servers'=>'Обойти предупреждения настройки базы данных (при активации плагина) на некоторых серверах','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Только для использования в разработке (подавляет предложение post_status = "опубликовать" для нефильтрованных типов сообщений с анонимным пользователем)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Только для разработки (в интерфейсе не заменяйте предложение "post_status = "опубликовать" на отфильтрованный эквивалент)','Logged In'=>'Вошел В Систему','Not Logged In'=>'Не Вошедшие В Систему','Everyone'=>'каждый','Change Request Notifications'=>'Уведомления о запросе на изменение','Submitted Revision Editors'=>'Представленные изменения','Scheduled Change Notifications'=>'Уведомления о запланированных изменениях','Scheduled Revision Monitors'=>'Запланированный мониторинг ревизий','Authenticated site users, except for Administrators'=>'Авторизованные пользователи сайта, кроме администраторов','Anonymous users (not logged in)'=>'Анонимные пользователи (не вошедшие в систему)','All users (including anonymous)'=>'Все пользователи (включая анонимных)','All users with the WordPress role of %s'=>'Все пользователи с ролью WordPress %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s не будет работать, пока вы не обновите PHP до версии %2$s или более поздней. Текущая версия: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s не будет работать, пока вы не обновите %2$s до версии %3$s или более поздней.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s не будет работать, пока вы не обновите WordPress до версии %2$s или более поздней.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'Эта версия %1$s не может работать с вашей текущей версией %2$s. Пожалуйста, обновите его до %3$s или более поздней версии.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'Дубликат %1$s активированного модуля  (%2$s в папке %3$s).','Dismiss'=>'Отклонить','Custom Group'=>'Пользовательская группа','Custom Groups'=>'Пользовательские группы','Groups'=>'Группы','(using default capabilities due to invalid %s definition)'=>'(использовать возможности по умолчанию из-за недопустимого определения %s)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s %2$s %3$s- %4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s %2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'Ваш ключ лицензии истек. Для обновлений PublishPress Permissions Pro и приоритетной поддержки, %sпожалуйста, продлите%s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'Все пользователи с ролью WordPress %s','All users who are logged in and have a role on the site'=>'Все пользователи, которые вошли в систему и имеют роль на сайте','Users to notify when revisions are submitted'=>'Пользователи, которым нужно уведомить, когда отправляются изменения','Users to notify when scheduled revisions are published'=>'Пользователи, которым нужно уведомить, когда запланированные изменения публикуются','(login timed out)'=>'(время ожидания входа истекло)','View'=>'Посмотреть','Control assignment of selected terms to %s.'=>'Управление назначением выбранных терминов к %s.','Control if this %s can be selected as a Parent Page.'=>'Контроль того, может ли этот %s быть выбран в качестве родительской страницы.','Control editing of selected %s.'=>'Контролировать редактирование выбранного %s.','Control publishing of selected %s.'=>'Контролировать публикацию выбранного %s.','Control deletion of selected %s.'=>'Контролировать удаление выбранного %s.','Control term management for selected %s.'=>'Контролировать управление терминами для выбранного %s.','Control frontend viewing of selected %s.'=>'Контроль просмотра выбранного %s на фронтенде.','Control who can create a revision of this %s.'=>'Контролируйте, кто может создать ревизию этого %s.','Control who can submit a revision of this %s.'=>'Контролируйте, кто может отправить ревизию этого %s.','Control which terms can be set as a Parent of other terms.'=>'Контролируйте, какие термины могут быть установлены в качестве родительских для других терминов.','Allow users to manage selected terms.'=>'Позвольте пользователям управлять выбранными терминами.','Control management of selected groups.'=>'Управление выбранными группами.','Enable'=>'Включить','Block'=>'Блок','Limit to'=>'Ограничить до','Expand access to allow specified items regardless of role capabilities or restrictions.'=>'Расширьте доступ, чтобы разрешить указанные элементы независимо от возможностей или ограничений ролей.','Restrict access by blocking specified items unless an "Enabled" exception is also stored.'=>'Ограничьте доступ, блокируя указанные элементы, если также не хранится исключение "Включено".','Restrict access by limiting role capabilities to apply only for specified items. Users still need capabilities in their main role or extra roles.'=>'Ограничьте доступ, ограничив возможности ролей так, чтобы они применялись только к указанным элементам. Пользователи все равно должны иметь возможности в своей главной роли или дополнительных ролях.','Using group membership to block access is not recommended. Consider reducing the user\'s role capabilities and using group membership to add access.'=>'Использование членства в группе для блокировки доступа не рекомендуется. Рассмотрите возможность уменьшения возможностей роли пользователя и использования членства в группе для добавления доступа.','Selected:'=>'Выбрано:','Nav Menus (Legacy)'=>'Меню навигации (устаревшие)','Legacy'=>'Наследие','%s:'=>'%s:','Selected %s:'=>'Выбрано %s:','Sub-%s:'=>'Под-%s:','All Statuses'=>'Все статусы','%s Visibility'=>'Видимость %s','No user/group specified.'=>'Пользователь/группа не указаны.','You are not permitted to do that.'=>'Вам не разрешается этого делать.','Invalid user ID.'=>'Неверный идентификатор пользователя.','Invalid group ID.'=>'Неверный идентификатор группы.','Roles updated.'=>'Роли обновлены.','Specific Permissions updated.'=>'Обновлены Особые разрешения.','Roles and Permissions copied.'=>'Роли и разрешения скопированы.','Group updated.'=>'Группа обновлена.','Back to permissions list'=>'Вернуться к списку разрешений','Edit User Permissions'=>'Изменение Разрешений пользователей','Add User Permissions'=>'Добавление Разрешения Пользователям','Edit Permissions'=>'Права на редактирование','Edit Permissions (%s)'=>'Разрешения на редактирование (%s)','%sEdit WordPress Role%s'=>'%sРедактировать роль WordPress%s','Edit role capabilities directly'=>'Прямое редактирование возможностей ролей','Add New'=>'Добавить новую','Name:'=>'Имя:','Email:'=>'Электронная почта:','Primary Role:'=>'Основная роль:','User ID:'=>'ID пользователя:','Member since:'=>'Участник с:','Description:'=>'Описание:','Update Permissions'=>'Обновить разрешения','View Full Profile'=>'Просмотреть полный профиль','Extra Roles %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Дополнительные роли %1$s(из основной роли или %2$sgroup membership%3$s)%4$s','Specific Permissions %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Конкретные разрешения %1$s(из основной роли или %2$sgroup membership%3$s)%4$s','View currently stored user permissions:'=>'Просмотр сохраненных в настоящее время разрешений пользователя:','%1$sUsers who have Extra Roles assigned directly%2$s'=>'%1$sПользователи, которым назначены дополнительные роли напрямую%2$s','%1$sUsers who have Specific Permissions assigned directly%2$s'=>'%1$sПользователи, которым напрямую назначены Особые разрешения%2$s','%1$sUsers who have Extra Roles or Specific Permissions directly%2$s'=>'%1$sПользователи, имеющие дополнительные роли или конкретные разрешения напрямую%2$s','Add Roles'=>'Добавить роль','Clear'=>'Очистить','No statuses selected!'=>'Статусы не выбраны!','Review the selection below, and then click <strong>Save Roles</strong>.'=>'